#!/usr/bin/env python3
"""Dr Moagi / JARVIS-X — 3D sparse AE/AD transactional reference, v1.

This is a single-file, standard-library, byte-exact 3D codec with optional
PyTorch neural experiments. Its generated release is exactly 1,000,000 bytes
and includes deterministic 3D regression reference vectors in source comments.

Core sequence:
 INGEST -> typed 3D tile -> reversible encode -> adaptive predictor candidate
 -> decode independently -> verify -> atomic commit -> audit receipt -> recur.

The 8e12-bit/axis universe is LOGICAL. Only 32^3-voxel tiles are resident.
A fixed-point residual is not a substitute for reconstruction correctness,
world correspondence, authentication, or human authorization.

Usage:
 python Dr_Moagi_1MB_3D_Engine.py selftest
 python Dr_Moagi_1MB_3D_Engine.py demo --output-dir demo_out
 python Dr_Moagi_1MB_3D_Engine.py encode input.bin archive.dm3d
 python Dr_Moagi_1MB_3D_Engine.py decode archive.dm3d restored.bin
 python Dr_Moagi_1MB_3D_Engine.py inspect archive.dm3d
 python Dr_Moagi_1MB_3D_Engine.py fetch https://api.github.com/repos/Lord-Xido/Jarvis-X/events repo.dm3d
 python Dr_Moagi_1MB_3D_Engine.py neural-demo --steps 5
"""
from __future__ import annotations

import argparse
import hashlib
import io
import json
import math
import os
import pathlib
import struct
import sys
import tempfile
import time
import urllib.error
import urllib.parse
import urllib.request
import zlib
from dataclasses import dataclass, field
from typing import BinaryIO, Iterable, Optional

VERSION = "DM3D-AEAD-v2"
MAGIC = b"DM3DAE02"
SIDE = 32
TILE_BYTES = SIDE ** 3
VIRTUAL_AXIS_BITS = 8_000_000_000_000
MAX_BYTES_DEFAULT = 64 * 1024 * 1024
MAX_HEADER = 65536
# index:Q, decoded_len:I, payload_len:I, mode:B, fixed-point weights:4i,
# decoded SHA256:32s, encoded SHA256:32s
FRAME = struct.Struct(">QIIB4i32s32s")
MODE_RAW, MODE_ZLIB, MODE_DELTA, MODE_PREDICT = range(4)
MODE_NAMES = ("raw", "zlib", "xyz-delta-zlib", "learned-predict-zlib")
# Four proper orthogonal cube rotations: identity plus 90-degree turns about
# each axis. The high bits of mode store the rotation; low two store the codec.
ROTATIONS = (
    ((0,1,2),(0,0,0)),
    ((1,0,2),(0,1,0)),
    ((2,1,0),(0,0,1)),
    ((0,2,1),(0,0,1)),
)
WEIGHT_LIMIT = 512
BIAS_LIMIT = 255 * 256
DEFAULT_WEIGHTS = (0, 256, 0, 0)  # bias, x, y, z in Q8.8


class InvalidArchive(ValueError):
    """Archive is corrupt, oversized, truncated, or violates the codec contract."""


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def canon_json(x: object) -> bytes:
    return json.dumps(x, sort_keys=True, separators=(",", ":"), ensure_ascii=True,
                      allow_nan=False).encode("ascii")


def morton3(x: int, y: int, z: int) -> int:
    """Unbounded integer Morton code; no 21-bit coordinate truncation."""
    if not all(isinstance(i, int) and 0 <= i < VIRTUAL_AXIS_BITS for i in (x, y, z)):
        raise ValueError("3D coordinates outside declared virtual axis")
    answer = 0
    for i in range(max(x.bit_length(), y.bit_length(), z.bit_length())):
        answer |= ((x >> i) & 1) << (3 * i)
        answer |= ((y >> i) & 1) << (3 * i + 1)
        answer |= ((z >> i) & 1) << (3 * i + 2)
    return answer


def unmorton3(key: int) -> tuple[int, int, int]:
    if not isinstance(key, int) or key < 0 or key.bit_length() > 3 * VIRTUAL_AXIS_BITS.bit_length():
        raise ValueError("invalid Morton address")
    out = [0, 0, 0]
    for i in range((key.bit_length() + 2) // 3):
        for axis in range(3):
            out[axis] |= ((key >> (3 * i + axis)) & 1) << i
    return tuple(out)


def chunk_coord(index: int, grid: int, origin: tuple[int, int, int]) -> tuple[int, int, int]:
    if grid <= 0 or index < 0:
        raise ValueError("invalid spatial chunk position")
    x = origin[0] + index % grid
    y = origin[1] + (index // grid) % grid
    z = origin[2] + index // (grid * grid)
    if any(c >= VIRTUAL_AXIS_BITS // SIDE or c < 0 for c in (x, y, z)):
        raise ValueError("spatial chunk coordinate beyond virtual axis")
    return (x, y, z)


def validate_spatial_extent(tiles: int, grid: int, origin: tuple[int,int,int]) -> None:
    secure_origin(origin)
    if tiles:
        maximum = (origin[0]+min(grid-1,tiles-1),
                   origin[1]+min(grid-1,(tiles-1)//grid),
                   origin[2]+(tiles-1)//(grid*grid))
        if any(i >= VIRTUAL_AXIS_BITS//SIDE for i in maximum):
            raise ValueError("spatial extent crosses logical axis boundary")


def cube_rotate(raw: bytes, rot: int, inverse: bool=False) -> bytes:
    """Bijective 3D proper rotation with an explicit inverse."""
    if len(raw)!=TILE_BYTES or not (0<=rot<len(ROTATIONS)):
        raise ValueError("invalid cube rotation or tile length")
    if rot==0: return raw
    perm, flip=ROTATIONS[rot]
    result=bytearray(TILE_BYTES)
    for z in range(SIDE):
        for y in range(SIDE):
            for x in range(SIDE):
                coords=(x,y,z)
                dstcoords=tuple(SIDE-1-coords[perm[a]] if flip[a] else coords[perm[a]] for a in range(3))
                source=(z*SIDE+y)*SIDE+x
                dest=(dstcoords[2]*SIDE+dstcoords[1])*SIDE+dstcoords[0]
                if inverse: result[source]=raw[dest]
                else: result[dest]=raw[source]
    return bytes(result)


def xyz_delta_encode(raw: bytes) -> bytes:
    if len(raw) != TILE_BYTES:
        raise ValueError("expected one 32-cube tile")
    a = bytearray(raw)
    # Backwards in every axis to reference still-unmodified predecessors.
    for base in range(0, TILE_BYTES, SIDE):
        for x in range(SIDE-1, 0, -1):
            i = base + x
            a[i] = (a[i] - a[i-1]) & 255
    for base in range(0, TILE_BYTES, SIDE*SIDE):
        for y in range(SIDE-1, 0, -1):
            for x in range(SIDE):
                i = base+y*SIDE+x
                a[i] = (a[i]-a[i-SIDE]) & 255
    for z in range(SIDE-1, 0, -1):
        for i in range(SIDE*SIDE):
            p = z*SIDE*SIDE+i
            a[p] = (a[p]-a[p-SIDE*SIDE]) & 255
    return bytes(a)


def xyz_delta_decode(encoded: bytes) -> bytes:
    if len(encoded) != TILE_BYTES:
        raise InvalidArchive("delta field length mismatch")
    a = bytearray(encoded)
    for z in range(1, SIDE):
        for i in range(SIDE*SIDE):
            p = z*SIDE*SIDE+i
            a[p] = (a[p]+a[p-SIDE*SIDE]) & 255
    for base in range(0, TILE_BYTES, SIDE*SIDE):
        for y in range(1, SIDE):
            for x in range(SIDE):
                i = base+y*SIDE+x
                a[i] = (a[i]+a[i-SIDE]) & 255
    for base in range(0, TILE_BYTES, SIDE):
        for x in range(1, SIDE):
            i = base+x
            a[i] = (a[i]+a[i-1]) & 255
    return bytes(a)


def pred(neighbors: tuple[int, int, int], weights: tuple[int, int, int, int]) -> int:
    b, wx, wy, wz = weights
    q = b + wx*neighbors[0] + wy*neighbors[1] + wz*neighbors[2]
    return min(255, max(0, (q+128)//256))


def local_neighbors(data: bytes | bytearray, i: int) -> tuple[int, int, int]:
    x = i % SIDE
    y = (i//SIDE) % SIDE
    z = i//(SIDE*SIDE)
    return (data[i-1] if x else 0,
            data[i-SIDE] if y else 0,
            data[i-SIDE*SIDE] if z else 0)


def predict_encode(raw: bytes, weights: tuple[int, int, int, int]) -> bytes:
    if len(raw) != TILE_BYTES:
        raise ValueError("expected a full tile")
    out = bytearray(TILE_BYTES)
    for i in range(TILE_BYTES):
        out[i] = (raw[i]-pred(local_neighbors(raw,i),weights)) & 255
    return bytes(out)


def predict_decode(err: bytes, weights: tuple[int, int, int, int]) -> bytes:
    if len(err) != TILE_BYTES:
        raise InvalidArchive("predictive residual length mismatch")
    out = bytearray(TILE_BYTES)
    for i in range(TILE_BYTES):
        out[i] = (err[i]+pred(local_neighbors(out,i),weights)) & 255
    return bytes(out)


def guarded_decompress(data: bytes, limit: int = TILE_BYTES) -> bytes:
    try:
        decoder = zlib.decompressobj()
        raw = decoder.decompress(data, limit+1)
        if len(raw) != limit or not decoder.eof or decoder.unconsumed_tail or decoder.unused_data:
            raise InvalidArchive("compressed frame does not expand to exactly one bounded tile")
        if decoder.flush():
            raise InvalidArchive("unexpected trailing decompression output")
        return raw
    except zlib.error as exc:
        raise InvalidArchive("zlib frame failed integrity parsing") from exc


def decode_payload(mode: int, payload: bytes, w: tuple[int,int,int,int]) -> bytes:
    rot, kind = divmod(mode, 4)
    if not (0<=rot<len(ROTATIONS)): raise InvalidArchive("unknown cube rotation")
    if kind == MODE_RAW:
        if len(payload) != TILE_BYTES: raise InvalidArchive("raw frame wrong size")
        transformed=payload
    else:
        expanded=guarded_decompress(payload)
        if kind==MODE_ZLIB: transformed=expanded
        elif kind==MODE_DELTA: transformed=xyz_delta_decode(expanded)
        elif kind==MODE_PREDICT: transformed=predict_decode(expanded,w)
        else: raise InvalidArchive("unsupported mode")
    return cube_rotate(transformed,rot,inverse=True)


def encode_payload(raw: bytes, weights: tuple[int,int,int,int]) -> tuple[int, bytes]:
    if len(raw) != TILE_BYTES:
        raise ValueError("source tile must be padded to SIDE^3")
    candidates=[]
    for rot in range(len(ROTATIONS)):
        transformed=cube_rotate(raw,rot)
        candidates.extend([
            (4*rot+MODE_RAW,transformed),
            (4*rot+MODE_ZLIB,zlib.compress(transformed,6)),
            (4*rot+MODE_DELTA,zlib.compress(xyz_delta_encode(transformed),6)),
            (4*rot+MODE_PREDICT,zlib.compress(predict_encode(transformed,weights),6)),
        ])
    best=min(candidates,key=lambda p:(len(p[1]),p[0]))
    if decode_payload(best[0],best[1],weights)!=raw:
        raise AssertionError("selected 3D rotation and codec did not round-trip")
    return best


def solve4(matrix: list[list[float]], rhs: list[float]) -> Optional[list[float]]:
    a = [r[:] + [rhs[i]] for i, r in enumerate(matrix)]
    for i in range(4):
        pivot = max(range(i, 4), key=lambda j: abs(a[j][i]))
        if abs(a[pivot][i]) < 1e-12:
            return None
        a[i],a[pivot] = a[pivot],a[i]
        denom = a[i][i]
        for c in range(i,5):
            a[i][c] /= denom
        for r in range(4):
            if r==i: continue
            mult=a[r][i]
            for c in range(i,5):
                a[r][c] -= mult*a[i][c]
    out = [a[i][4] for i in range(4)]
    return out if all(math.isfinite(v) for v in out) else None


def heldout_mse(raw: bytes, weights: tuple[int,int,int,int], stride: int = 17, offset: int = 0) -> float:
    total = 0
    count = 0
    for i in range(offset,TILE_BYTES,stride):
        e = raw[i]-pred(local_neighbors(raw,i),weights)
        total += e*e
        count += 1
    return total/max(1,count)


def ridge_candidate(raw: bytes) -> Optional[tuple[int,int,int,int]]:
    """Fit a 4-weight linear spatial predictor on non-validation points."""
    mat = [[0.0]*4 for _ in range(4)]
    rhs = [0.0]*4
    for i in range(1,TILE_BYTES,13):
        if i % 17 == 0: continue
        l,u,b=local_neighbors(raw,i)
        features = (1.0,l/255.0,u/255.0,b/255.0)
        target=raw[i]/255.0
        for j in range(4):
            rhs[j]+=features[j]*target
            for k in range(4):
                mat[j][k]+=features[j]*features[k]
    for j in range(4): mat[j][j]+=0.025
    w = solve4(mat, rhs)
    if w is None: return None
    cand=(round(w[0]*255*256),round(w[1]*256),round(w[2]*256),round(w[3]*256))
    return (max(-BIAS_LIMIT,min(BIAS_LIMIT,cand[0])),
            *(max(-WEIGHT_LIMIT,min(WEIGHT_LIMIT,x)) for x in cand[1:]))


@dataclass
class AdaptivePolicy:
    weights: tuple[int,int,int,int] = DEFAULT_WEIGHTS
    accepted: int = 0
    rejected: int = 0
    anchor: Optional[bytes] = None
    last_holdout_mse: Optional[float] = None
    evolution: list[dict] = field(default_factory=list)

    def step(self, tile: bytes, chunk_index: int) -> None:
        if self.anchor is None: self.anchor = tile
        proposal=ridge_candidate(tile)
        if proposal is None:
            self.rejected+=1
            return
        old=heldout_mse(tile,self.weights)
        new=heldout_mse(tile,proposal)
        old_anchor=heldout_mse(self.anchor,self.weights)
        new_anchor=heldout_mse(self.anchor,proposal)
        promote = new + 1e-9 < old and new_anchor <= old_anchor*1.03+1e-8
        if promote:
            self.weights=proposal
            self.accepted+=1
        else:
            self.rejected+=1
        self.last_holdout_mse=new if promote else old
        self.evolution.append({"chunk":chunk_index,"promoted":promote,
                               "candidate_mse":round(new,6),"baseline_mse":round(old,6),
                               "anchor_mse":round(new_anchor,6)})

    def to_state(self)->dict:
        return {"schema":"DM3D-POLICY-1","weights":list(self.weights),
                "accepted":self.accepted,"rejected":self.rejected,
                "last_holdout_mse":self.last_holdout_mse}


def validated_weights(value: object) -> tuple[int,int,int,int]:
    if not isinstance(value,list) or len(value)!=4 or any(type(v) is not int for v in value):
        raise ValueError("invalid packet model weights")
    w=tuple(value)
    if abs(w[0])>BIAS_LIMIT or any(abs(v)>WEIGHT_LIMIT for v in w[1:]):
        raise ValueError("packet model weights outside safety bounds")
    return w


def write_atomic(path: pathlib.Path, callback) -> None:
    path=path.resolve()
    path.parent.mkdir(parents=True,exist_ok=True)
    fd, tmp=tempfile.mkstemp(prefix=".dm3d-",dir=path.parent)
    try:
        with os.fdopen(fd,"wb") as stream:
            callback(stream)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(tmp,path)
    finally:
        try: os.unlink(tmp)
        except FileNotFoundError: pass


def read_exact(f: BinaryIO, n: int) -> bytes:
    if n<0 or n>MAX_BYTES_DEFAULT+MAX_HEADER:
        raise InvalidArchive("invalid bounded read length")
    data=f.read(n)
    if len(data)!=n: raise InvalidArchive("truncated archive")
    return data


def secure_origin(origin: tuple[int,int,int]) -> tuple[int,int,int]:
    if any(i<0 or i>=VIRTUAL_AXIS_BITS//SIDE for i in origin):
        raise ValueError("origin must be a valid 32-bit-cube coordinate")
    return origin


def encode_file(source: pathlib.Path, destination: pathlib.Path,
                *, max_bytes: int=MAX_BYTES_DEFAULT,
                origin: tuple[int,int,int]=(0,0,0), state_file:Optional[pathlib.Path]=None) -> dict:
    secure_origin(origin)
    if source.resolve()==destination.resolve():
        raise ValueError("encoding must not overwrite its input")
    if state_file is not None and state_file.resolve() in (source.resolve(),destination.resolve()):
        raise ValueError("state path must not overwrite input or archive")
    size=source.stat().st_size
    if size>max_bytes or size<0:
        raise ValueError("source exceeds explicit resource budget")
    tiles=(size+TILE_BYTES-1)//TILE_BYTES
    grid=max(1,math.ceil(tiles**(1/3)))
    # Ensure floating-point cube-root cannot undercount very large tile counts.
    while grid**3 < tiles: grid+=1
    validate_spatial_extent(tiles,grid,origin)
    p=AdaptivePolicy()
    if state_file is not None and state_file.exists():
        if state_file.stat().st_size>4096:
            raise ValueError("state checkpoint exceeds 4 KiB safety limit")
        loaded=json.loads(state_file.read_text("utf-8"))
        if loaded.get("schema")!="DM3D-POLICY-1":
            raise ValueError("unsupported checkpoint schema")
        p.weights=validated_weights(loaded.get("weights"))
        # State is untrusted advisory policy; archive records independent weights.
    bytes_digest=hashlib.sha256()
    body_digest=hashlib.sha256()
    mode_counts={name:0 for name in MODE_NAMES}
    with tempfile.TemporaryFile(mode="w+b") as body:
        with source.open("rb") as stream:
            total=0
            for index in range(tiles):
                raw=stream.read(TILE_BYTES)
                if not raw: raise IOError("file changed while encoding")
                total+=len(raw)
                bytes_digest.update(raw)
                padded=raw.ljust(TILE_BYTES,b"\0")
                active_weights=p.weights
                mode,payload=encode_payload(padded,active_weights)
                if len(payload)>TILE_BYTES: raise AssertionError("mode selector exceeded tile budget")
                frame=FRAME.pack(index,len(raw),len(payload),mode,*active_weights,
                                 hashlib.sha256(padded).digest(),hashlib.sha256(payload).digest())
                body.write(frame);body.write(payload)
                body_digest.update(frame);body_digest.update(payload)
                mode_counts[MODE_NAMES[mode%4]]+=1
                p.step(padded,index)
            if stream.read(1): raise IOError("source grew during encoding")
            if total!=size: raise IOError("source changed size during encoding")
        hdr={"format":VERSION,"side":SIDE,"tile_bytes":TILE_BYTES,
             "logical_axis_bits":str(VIRTUAL_AXIS_BITS),"origin_chunks":[str(o) for o in origin],
             "grid_width":grid,"original_bytes":size,"original_sha256":bytes_digest.hexdigest(),
             "packet_count":tiles,"body_sha256":body_digest.hexdigest(),
             "codec":"lossless-hybrid-3d-reversible","mode_counts":mode_counts,
             "adaptive_policy":{"start":list(DEFAULT_WEIGHTS),"end":list(p.weights),
                                "updates_accepted":p.accepted,"updates_rejected":p.rejected},
             "authority":"local-candidate-verified-commit",
             "external_correspondence":"not_evaluated"}
        header_bytes=canon_json(hdr)
        if len(header_bytes)>MAX_HEADER:
            raise ValueError("archive header exceeds budget")
        def write_archive(out:BinaryIO)->None:
            out.write(MAGIC);out.write(struct.pack(">I",len(header_bytes)));out.write(header_bytes)
            out.write(hashlib.sha256(header_bytes).digest())
            body.seek(0)
            while True:
                piece=body.read(262144)
                if not piece: break
                out.write(piece)
        write_atomic(destination,write_archive)
    if state_file is not None:
        write_atomic(state_file,lambda out: out.write(canon_json(p.to_state())+b"\n"))
    hdr["archive_bytes"]=destination.stat().st_size
    hdr["compression_ratio_in_to_out"]=round(size/hdr["archive_bytes"],5) if hdr["archive_bytes"] else 0
    return hdr


def check_header(header: object, max_bytes: int) -> dict:
    if not isinstance(header,dict) or header.get("format")!=VERSION:
        raise InvalidArchive("unsupported archive format/version")
    if header.get("side")!=SIDE or header.get("tile_bytes")!=TILE_BYTES:
        raise InvalidArchive("invalid 3D tile schema")
    size=header.get("original_bytes")
    tiles=header.get("packet_count")
    grid=header.get("grid_width")
    if any(type(v) is not int for v in (size,tiles,grid)):
        raise InvalidArchive("invalid archive sizes")
    if not (0<=size<=max_bytes and 0<=tiles<=(max_bytes+TILE_BYTES-1)//TILE_BYTES):
        raise InvalidArchive("archive exceeds resource limits")
    if tiles!=(size+TILE_BYTES-1)//TILE_BYTES or grid<1 or grid**3<tiles:
        raise InvalidArchive("invalid 3D packet geometry")
    origin_str=header.get("origin_chunks")
    if (not isinstance(origin_str,list) or len(origin_str)!=3
            or any(not isinstance(s,str) or not s.isdigit() or len(s)>14 for s in origin_str)):
        raise InvalidArchive("invalid logical origin encoding")
    origin=tuple(int(s) for s in origin_str)
    secure_origin(origin)
    try: validate_spatial_extent(tiles,grid,origin)
    except ValueError as ex: raise InvalidArchive(str(ex)) from ex
    for item in ("original_sha256","body_sha256"):
        v=header.get(item)
        if not isinstance(v,str) or len(v)!=64 or any(c not in "0123456789abcdef" for c in v):
            raise InvalidArchive("invalid checksum metadata")
    if header.get("codec")!="lossless-hybrid-3d-reversible":
        raise InvalidArchive("unknown codec semantics")
    return header


def decode_file(archive:pathlib.Path,destination:pathlib.Path,
                *,max_bytes:int=MAX_BYTES_DEFAULT)->dict:
    if archive.resolve()==destination.resolve():
        raise InvalidArchive("decoding must not overwrite its archive")
    with archive.open("rb") as input_stream:
        if read_exact(input_stream,8)!=MAGIC: raise InvalidArchive("archive magic mismatch")
        header_len=struct.unpack(">I",read_exact(input_stream,4))[0]
        if header_len>MAX_HEADER: raise InvalidArchive("archive header oversized")
        header_bytes=read_exact(input_stream,header_len)
        if hashlib.sha256(header_bytes).digest()!=read_exact(input_stream,32):
            raise InvalidArchive("archive header SHA-256 mismatch")
        try: header=check_header(json.loads(header_bytes),max_bytes)
        except (UnicodeDecodeError,json.JSONDecodeError,TypeError,ValueError) as exc:
            raise InvalidArchive("header rejected") from exc
        sha_original=hashlib.sha256()
        sha_body=hashlib.sha256()
        total=0
        def reconstruct(out:BinaryIO)->None:
            nonlocal total
            for index in range(header["packet_count"]):
                fb=read_exact(input_stream,FRAME.size)
                sha_body.update(fb)
                packet_idx,n_orig,n_packed,mode,*tail=FRAME.unpack(fb)
                weights=tail[:4]
                raw_hash,packed_hash=tail[4:]
                if packet_idx!=index or mode>=4*len(ROTATIONS) or n_packed>TILE_BYTES:
                    raise InvalidArchive("invalid packet mode/index/size")
                expected_length = (header["original_bytes"]-(index*TILE_BYTES))
                if index<header["packet_count"]-1: expected_length=TILE_BYTES
                if n_orig!=expected_length:
                    raise InvalidArchive("inconsistent packet decoded length")
                try: validated_weights(list(weights))
                except ValueError as exc: raise InvalidArchive("invalid packet predictor") from exc
                payload=read_exact(input_stream,n_packed)
                sha_body.update(payload)
                if hashlib.sha256(payload).digest()!=packed_hash:
                    raise InvalidArchive("compressed packet SHA-256 mismatch")
                restored=decode_payload(mode,payload,tuple(weights))
                if hashlib.sha256(restored).digest()!=raw_hash:
                    raise InvalidArchive("reconstructed tile SHA-256 mismatch")
                if any(restored[n_orig:]):
                    raise InvalidArchive("padding not zero")
                piece=restored[:n_orig]
                out.write(piece);sha_original.update(piece);total+=len(piece)
            if input_stream.read(1): raise InvalidArchive("trailing archive data rejected")
            if total!=header["original_bytes"]:
                raise InvalidArchive("decoded size disagrees with header")
            if sha_body.hexdigest()!=header["body_sha256"]:
                raise InvalidArchive("body checksum mismatch")
            if sha_original.hexdigest()!=header["original_sha256"]:
                raise InvalidArchive("original SHA-256 mismatch")
        write_atomic(destination,reconstruct)
    return {"format":VERSION,"decision":"COMMIT","input_archive":str(archive),
            "output":str(destination),"decoded_bytes":total,
            "verified_sha256":sha_original.hexdigest(),
            "external_correspondence":"not_evaluated"}


def inspect_file(path:pathlib.Path,*,max_bytes:int=MAX_BYTES_DEFAULT)->dict:
    # Inspect is non-authoritative; decode to a safe temporary destination to verify all bytes.
    with tempfile.TemporaryDirectory() as temporary:
        receipt=decode_file(path,pathlib.Path(temporary)/"verified.bin",max_bytes=max_bytes)
    return {"verified":True,"archive_bytes":path.stat().st_size,**receipt}


def reference_tile(seed:int)->bytes:
    """Deterministic 8^3 spatial fixture, independent of hash randomization."""
    result=bytearray(512)
    for z in range(8):
        for y in range(8):
            for x in range(8):
                a=((x*17+y*31+z*47+seed*29)^((x*y+seed*z+3*x*z)*13))&255
                result[z*64+y*8+x]=a
    return bytes(result)


def synthetic_tile(index:int,seed:int)->bytes:
    result=bytearray(TILE_BYTES)
    kind=index%5
    center=(seed+index)%SIDE
    for z in range(SIDE):
        for y in range(SIDE):
            for x in range(SIDE):
                j=(z*SIDE+y)*SIDE+x
                if kind==0:
                    result[j]=255 if ((x-center)**2+(y-16)**2+(z-16)**2)<121 else 0
                elif kind==1:
                    result[j]=(x*3+y*5+z*7+index*11)&255
                elif kind==2:
                    result[j]=255 if (x//4+y//4+z//4+index)&1 else 0
                elif kind==3:
                    result[j]=255 if (abs(x-16)<5 and abs(y-16)<8 and abs(z-16)<6) else 0
                else:
                    result[j]=((x*17)^(y*37)^(z*73)^(index*19))&255
    return bytes(result)


def generate_demo_blob(out:BinaryIO,nbytes:int,seed:int)->str:
    h=hashlib.sha256()
    remaining=nbytes; index=0
    while remaining:
        data=synthetic_tile(index,seed)[:min(TILE_BYTES,remaining)]
        out.write(data);h.update(data)
        remaining-=len(data);index+=1
    return h.hexdigest()


def no_redirect_http(url:str,limit:int,timeout:float)->bytes:
    """Read public GitHub REST events only, strict HTTPS and redirect refusal."""
    parsed=urllib.parse.urlparse(url)
    if (parsed.scheme!="https" or parsed.hostname!="api.github.com"
        or parsed.username or parsed.password or parsed.port not in (None,443)
        or not parsed.path.startswith("/repos/") or not parsed.path.endswith("/events")):
        raise ValueError("only https://api.github.com/repos/<owner>/<repo>/events is allowed")
    parts=parsed.path.split("/")
    if len(parts)!=5 or any(not p for p in parts[2:4]):
        raise ValueError("invalid public GitHub events API path")
    if limit<1 or limit>MAX_BYTES_DEFAULT: raise ValueError("invalid fetch byte cap")
    class DenyRedirect(urllib.request.HTTPRedirectHandler):
        def redirect_request(self,*args,**kwargs):
            raise ValueError("external redirects are disabled")
    opener=urllib.request.build_opener(DenyRedirect)
    req=urllib.request.Request(url,headers={"User-Agent":"DM3D-AEAD-Reference/1.0",
                                                   "Accept":"application/vnd.github+json",
                                                   "Accept-Encoding":"identity"})
    with opener.open(req,timeout=timeout) as response:
        if response.status!=200: raise IOError(f"GitHub returned HTTP {response.status}")
        data=response.read(limit+1)
    if len(data)>limit: raise ValueError("WWW response exceeds permitted byte budget")
    try:
        payload=json.loads(data)
        if not isinstance(payload,list): raise ValueError("expected JSON event array")
    except (UnicodeDecodeError,json.JSONDecodeError) as exc:
        raise ValueError("unexpected WWW response") from exc
    return data


def neural_demo(steps:int,checkpoint:pathlib.Path,seed:int=7)->dict:
    """Optional PyTorch experiment; separate from lossless archive protocol.

    Neural training is demonstrative, not a pretrained cognitive or semantic model.
    The latent map is contractive; updates are accepted by held-out MSE.
    """
    try:
        import torch
        import torch.nn as nn
        import torch.nn.functional as F
    except ImportError as exc:
        raise RuntimeError("optional neural demo requires 'pip install torch'") from exc
    torch.manual_seed(seed)
    torch.set_num_threads(min(4,torch.get_num_threads()))
    class Neural3D(nn.Module):
        def __init__(self):
            super().__init__()
            self.enc=nn.Sequential(nn.Conv3d(1,4,3,stride=2,padding=1),nn.ReLU(),
                                   nn.Conv3d(4,8,3,stride=2,padding=1),nn.ReLU(),
                                   nn.AdaptiveAvgPool3d(4))
            self.dec=nn.Sequential(nn.ConvTranspose3d(8,8,4,stride=2,padding=1),nn.ReLU(),
                                   nn.ConvTranspose3d(8,4,4,stride=2,padding=1),nn.ReLU(),
                                   nn.ConvTranspose3d(4,1,4,stride=2,padding=1))
        def inward(self,z,iterations=10):
            origin=z
            for _ in range(iterations):
                offset=z-origin
                avg=sum(torch.roll(offset,shifts=s,dims=d) for d in (2,3,4) for s in (-1,1))/6
                z=origin+0.4*torch.tanh(avg+0.2*torch.tanh(origin))
            return z
        def forward(self,x):
            return torch.sigmoid(self.dec(self.inward(self.enc(x))))
    model=Neural3D()
    opt=torch.optim.Adam(model.parameters(),lr=0.003)
    def tensor_input(i):
        buf=synthetic_tile(i,seed)
        return torch.tensor(list(buf),dtype=torch.float32).view(1,1,SIDE,SIDE,SIDE)/255.0
    train=[tensor_input(i) for i in range(4)]
    dev=[tensor_input(i) for i in range(9,13)]
    def evaluate():
        model.eval()
        with torch.no_grad():
            return sum(float(F.mse_loss(model(x),x)) for x in dev)/len(dev)
    baseline=evaluate()
    best=baseline
    accepted=0
    # Candidate optimizer state is rolled back together with model parameters.
    for step in range(steps):
        model_before={k:v.detach().clone() for k,v in model.state_dict().items()}
        import copy
        optimizer_before=copy.deepcopy(opt.state_dict())
        model.train()
        x=train[step%len(train)]
        loss=F.mse_loss(model(x),x)
        opt.zero_grad();loss.backward()
        torch.nn.utils.clip_grad_norm_(model.parameters(),1.0)
        opt.step()
        trial=evaluate()
        if math.isfinite(trial) and trial<=best+1e-10:
            best=trial;accepted+=1
        else:
            model.load_state_dict(model_before)
            opt.load_state_dict(optimizer_before)
    # The checkpoint can be loaded with torch.load(..., weights_only=True).
    checkpoint.parent.mkdir(parents=True,exist_ok=True)
    temp=checkpoint.with_suffix(".candidate.pt")
    torch.save({"schema":"DM3D-Neural-1","weights":model.state_dict(),
                "baseline_mse":baseline,"validation_mse":best,
                "training_steps":steps,"accepted":accepted},temp)
    os.replace(temp,checkpoint)
    return {"neural":"experimental","baseline_mse":baseline,"best_mse":best,
            "steps":steps,"accepted":accepted,"checkpoint":str(checkpoint),
            "model_contract":"lossy-geometric-3d-only"}


def selftest(check_vectors:bool=False)->dict:
    import random
    rng=random.Random(20261019)
    cases=0
    for coord in [(0,0,0),(1,2,3),(2**21,2**22,2**23),(10**11,10**11+1,10**11+2)]:
        assert unmorton3(morton3(*coord))==coord;cases+=1
    for seed in range(5):
        data=synthetic_tile(seed,7)
        assert xyz_delta_decode(xyz_delta_encode(data))==data;cases+=1
        for rot in range(len(ROTATIONS)):
            assert cube_rotate(cube_rotate(data,rot),rot,inverse=True)==data
            cases+=1
        for weights in [DEFAULT_WEIGHTS,(0,150,52,55),(0,-64,128,256)]:
            assert predict_decode(predict_encode(data,weights),weights)==data;cases+=1
        mode,payload=encode_payload(data,DEFAULT_WEIGHTS)
        assert decode_payload(mode,payload,DEFAULT_WEIGHTS)==data;cases+=1
    # Decoder isolation from mutable weight policy and corrupted payloads.
    with tempfile.TemporaryDirectory() as td:
        td=pathlib.Path(td)
        src=td/"sample.bin";dst=td/"output.dm3d";restore=td/"reconstructed.bin"
        with src.open("wb") as f: generate_demo_blob(f, 2*TILE_BYTES+271,7)
        receipt=encode_file(src,dst,state_file=td/"weight-policy.json")
        assert receipt["packet_count"]==3;cases+=1
        rec=decode_file(dst,restore)
        assert src.read_bytes()==restore.read_bytes()==src.read_bytes();cases+=1
        assert rec["decision"]=="COMMIT";cases+=1
        b=bytearray(dst.read_bytes())
        b[-5]^=128
        damage=td/"broken.dm3d";damage.write_bytes(b)
        try:
            decode_file(damage,td/"cannot-commit.bin")
            raise AssertionError("tampering was not rejected")
        except InvalidArchive: cases+=1
        assert not (td/"cannot-commit.bin").exists();cases+=1
        try:
            decode_file(dst,td/"resource-denied.bin",max_bytes=16)
            raise AssertionError("budget was not enforced")
        except InvalidArchive: cases+=1
        assert not (td/"resource-denied.bin").exists();cases+=1
        # Truncated record and extraneous data must not commit.
        for badbytes in [dst.read_bytes()[:-5],dst.read_bytes()+b"X"]:
            damage.write_bytes(badbytes)
            try: decode_file(damage,td/"incomplete.bin")
            except InvalidArchive: cases+=1
            else: raise AssertionError("malformed archive accepted")
        # Byte-perfect behavior for both compressible and high-entropy data.
        raw=bytes(rng.randrange(256) for _ in range(5001))
        src.write_bytes(raw)
        encode_file(src,dst)
        decode_file(dst,restore)
        assert restore.read_bytes()==raw;cases+=1
        src.write_bytes(b"")
        encode_file(src,dst)
        decode_file(dst,restore)
        assert restore.read_bytes()==b"";cases+=1
    # Regression: disallow destructive destination paths and excessive virtual offsets.
    with tempfile.TemporaryDirectory() as td2:
        inp=pathlib.Path(td2)/"in.bin"
        inp.write_bytes(b"hello")
        try: encode_file(inp,inp)
        except ValueError: cases+=1
        else: raise AssertionError("in-place encoding allowed")
        arc=pathlib.Path(td2)/"in.dm3d"
        encode_file(inp,arc)
        try: decode_file(arc,arc)
        except InvalidArchive: cases+=1
        else: raise AssertionError("in-place decoding allowed")
        try: encode_file(inp, pathlib.Path(td2)/"x.dm3d",origin=(VIRTUAL_AXIS_BITS//SIDE,0,0))
        except ValueError: cases+=1
        else: raise AssertionError("out-of-bounds virtual origin allowed")
    if check_vectors:
        # Each appended reference line is a deterministic 3D SHA-256 fixture.
        source=pathlib.Path(__file__).read_text("utf-8")
        fixtures=0
        for line in source.splitlines():
            if not line.startswith("# 3DREF "): continue
            _,tag,seed_str,digest=line.split()
            if tag!="3DREF" or sha(reference_tile(int(seed_str)))!=digest:
                raise AssertionError(f"reference vector failed: {seed_str}")
            fixtures+=1
        assert fixtures>=5000
        cases+=fixtures
    return {"tests_passed":cases,"selftest":"PASS", "test_vectors_checked":check_vectors,
            "dependency":"python-standard-library", "sparse_virtual_axes_bits":str(VIRTUAL_AXIS_BITS)}


def json_print(item:object)->None:
    print(json.dumps(item,sort_keys=True,indent=2,allow_nan=False))


def cli(argv:Optional[list[str]]=None)->int:
    parser=argparse.ArgumentParser(description="Verified sparse 3D auto-encoding/decoding runtime")
    sub=parser.add_subparsers(dest="operation",required=True)
    p=sub.add_parser("encode",help="losslessly encode a file into 32^3 byte tiles")
    p.add_argument("input",type=pathlib.Path);p.add_argument("archive",type=pathlib.Path)
    p.add_argument("--origin",nargs=3,type=int,default=[0,0,0])
    p.add_argument("--max-bytes",type=int,default=MAX_BYTES_DEFAULT)
    p.add_argument("--state",type=pathlib.Path)
    p=sub.add_parser("decode",help="independently verify and restore exact input bytes")
    p.add_argument("archive",type=pathlib.Path);p.add_argument("output",type=pathlib.Path)
    p.add_argument("--max-bytes",type=int,default=MAX_BYTES_DEFAULT)
    p=sub.add_parser("inspect",help="verify archive without writing persistent output")
    p.add_argument("archive",type=pathlib.Path)
    p=sub.add_parser("selftest",help="run reversible geometry, integrity, and rollback tests")
    p.add_argument("--vectors",action="store_true",help="verify all embedded 3D reference vectors")
    p=sub.add_parser("demo",help="run deterministic 1MiB spatial roundtrip")
    p.add_argument("--output-dir",type=pathlib.Path,default=pathlib.Path("dm3d_demo"))
    p.add_argument("--size",type=int,default=1024*1024)
    p.add_argument("--seed",type=int,default=7)
    p=sub.add_parser("fetch",help="bounded HTTPS GitHub events -> verified 3D archive")
    p.add_argument("url",type=str);p.add_argument("archive",type=pathlib.Path)
    p.add_argument("--max-bytes",type=int,default=1024*1024)
    p.add_argument("--timeout",type=float,default=10.0)
    p=sub.add_parser("neural-demo",help="optional torch 3D contractive neural training")
    p.add_argument("--steps",type=int,default=5)
    p.add_argument("--checkpoint",type=pathlib.Path,default=pathlib.Path("dm3d_neural.pt"))
    args=parser.parse_args(argv)
    try:
        if args.operation=="encode":
            if args.max_bytes<0 or args.max_bytes>MAX_BYTES_DEFAULT: raise ValueError("max-bytes invalid")
            json_print(encode_file(args.input,args.archive,max_bytes=args.max_bytes,
                                   origin=tuple(args.origin),state_file=args.state))
        elif args.operation=="decode":
            json_print(decode_file(args.archive,args.output,max_bytes=args.max_bytes))
        elif args.operation=="inspect":json_print(inspect_file(args.archive))
        elif args.operation=="selftest":json_print(selftest(args.vectors))
        elif args.operation=="demo":
            if not (0<=args.size<=MAX_BYTES_DEFAULT): raise ValueError("demo size out of bounds")
            args.output_dir.mkdir(parents=True,exist_ok=True)
            source=args.output_dir/"1MiB_3D_input.bin"
            archive=args.output_dir/"1MiB_3D_archive.dm3d"
            restored=args.output_dir/"1MiB_3D_restored.bin"
            receipt=args.output_dir/"3D_transaction_receipt.json"
            with source.open("wb") as out: source_hash=generate_demo_blob(out,args.size,args.seed)
            enc=encode_file(source,archive,state_file=args.output_dir/"adaptive_policy.json")
            dec=decode_file(archive,restored)
            if source_hash!=dec["verified_sha256"]:
                raise AssertionError("transaction identity mismatch")
            result={"transaction":"DM3D-exact-roundtrip","encoding":enc,"decoding":dec,
                    "byte_exact":True,"source_sha256":source_hash,
                    "run_time_utc":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime())}
            write_atomic(receipt,lambda out:out.write(canon_json(result)+b"\n"))
            json_print(result)
        elif args.operation=="fetch":
            with tempfile.TemporaryDirectory() as td:
                source=pathlib.Path(td)/"github_events.json"
                source.write_bytes(no_redirect_http(args.url,args.max_bytes,args.timeout))
                result=encode_file(source,args.archive,max_bytes=args.max_bytes)
                result["provenance"]={"source":args.url,"kind":"public_github_events",
                                       "retrieved_at_utc":time.strftime("%Y-%m-%dT%H:%M:%SZ",time.gmtime())}
                json_print(result)
        elif args.operation=="neural-demo":
            if args.steps<0 or args.steps>200: raise ValueError("neural steps must be 0..200")
            json_print(neural_demo(args.steps,args.checkpoint))
        return 0
    except (OSError,InvalidArchive,ValueError,AssertionError,RuntimeError) as exc:
        print(json.dumps({"decision":"ROLLBACK","error":str(exc),"type":type(exc).__name__}),
              file=sys.stderr)
        return 2

if __name__ == "__main__":
    raise SystemExit(cli())

